/**
 * Builds the Open Graph share card and the favicon from the real logo.
 *
 *   npm run brand
 *
 * Both are generated, so do not edit public/images/og-default.png or
 * public/favicon.svg by hand. Change this file and re-run.
 *
 * The share card embeds the logo as a base64 data URI inside an SVG, then renders
 * that SVG to PNG. That keeps one source of truth: swap the logo master and both
 * the card and the site header follow.
 */

import { readFileSync, writeFileSync, statSync } from 'node:fs';
import sharp from 'sharp';

const LOGO = 'src/assets/brand/musafir-qi-logo-cutout.png';
const logoData = readFileSync(LOGO).toString('base64');
const logoUri = `data:image/png;base64,${logoData}`;

// Logo is 332x115. On the card it runs at 420 wide, so 145 tall.
const CARD = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630">
  <rect width="1200" height="630" fill="#DA291C"/>
  <rect x="0" y="0" width="1200" height="10" fill="#D4AF37"/>
  <rect x="0" y="620" width="1200" height="10" fill="#D4AF37"/>

  <image href="${logoUri}" x="84" y="96" width="420" height="145"/>

  <text x="84" y="360" font-family="Arial Narrow, Haettenschweiler, Impact, sans-serif"
        font-size="118" font-weight="700" fill="#F5D77A" letter-spacing="2">STESEN MALA</text>

  <text x="88" y="410" font-family="Segoe UI, Arial, sans-serif"
        font-size="30" font-weight="600" fill="#FFFFFF" letter-spacing="2">Hot Pot &#183; Charcoal Skewers &#183; Malatang</text>

  <rect x="88" y="446" width="150" height="4" fill="#D4AF37"/>

  <text x="88" y="504" font-family="Segoe UI, Arial, sans-serif"
        font-size="26" fill="#FFFFFF" opacity="0.85">Fill your own bowl. Pay for what you took.</text>
  <text x="88" y="548" font-family="Segoe UI, Arial, sans-serif"
        font-size="24" fill="#FFFFFF" opacity="0.7">CBD Perdana 3, Cyberjaya &#183; Pork free and lard free</text>
</svg>`;

writeFileSync('public/images/og-default.svg', CARD);
await sharp(Buffer.from(CARD)).png({ compressionLevel: 9 }).toFile('public/images/og-default.png');
console.log(
  `  og-default.png           1200x630  ${Math.round(statSync('public/images/og-default.png').size / 1024)}KB`
);

/**
 * Favicon. The full badge is unreadable at 16px, so this takes the two things that
 * survive at that size: the gold arch and the crescent, on the badge's dark ground.
 */
const FAVICON = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="48" height="48">
  <!-- Generated by scripts/build-brand-art.mjs from the Musafir Qi badge.
       Do not edit by hand. Run: npm run brand -->
  <rect width="48" height="48" rx="8" fill="#DA291C"/>
  <path d="M24 7c9.4 0 17 7.2 17 16.1V41H7V23.1C7 14.2 14.6 7 24 7Z" fill="#14100F"/>
  <path d="M24 10.5c7.5 0 13.5 5.7 13.5 12.8V41" fill="none" stroke="#D4AF37" stroke-width="2.2"/>
  <path d="M24 10.5c-7.5 0-13.5 5.7-13.5 12.8V41" fill="none" stroke="#D4AF37" stroke-width="2.2"/>
  <path d="M29.6 24.4a8 8 0 1 1-6.9-9.3 6.4 6.4 0 0 0 0 12.6 8 8 0 0 0 6.9-3.3Z" fill="#FFFFFF"/>
</svg>`;

writeFileSync('public/favicon.svg', FAVICON);
console.log(`  favicon.svg              48x48     ${statSync('public/favicon.svg').size}B`);
